1	<meta charset="utf-8">
2	<title>CD31 Stack Viewer</title>
3	<link rel="preconnect" href="https://fonts.googleapis.com">
4	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans+Condensed:wght@500;600&family=IBM+Plex+Sans:wght@400;500&display=swap">
5	<style>
6	  :root {
7	    color-scheme: dark;
8	    --ground: #0b0f12;
9	    --panel: #131a1f;
10	    --line: #25313a;
11	    --text: #d8e1e7;
12	    --muted: #82929d;
13	    --accent: #4fd1d9;
14	    --warn: #e8b04a;
15	    --mark: #ff4fd8;
16	    --sans: "IBM Plex Sans", system-ui, sans-serif;
17	    --cond: "IBM Plex Sans Condensed", "Arial Narrow", system-ui, sans-serif;
18	    --mono: "IBM Plex Mono", ui-monospace, monospace;
19	  }
20	  html, body { height: 100%; }
21	  body { background: var(--ground); color: var(--text); font: 14px/1.5 var(--sans); padding-inline: 16px; padding-block: 12px 24px; }
22	  header { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 16px; margin-bottom: 10px; }
23	  h1 { font: 600 22px/1.2 var(--cond); margin: 0; letter-spacing: .01em; text-wrap: balance; }
24	  .facts { display: flex; flex-wrap: wrap; gap: 4px 14px; font: 12px var(--mono); color: var(--muted); font-variant-numeric: tabular-nums; }
25	  .facts b { color: var(--text); font-weight: 500; }
26	  .guess { color: var(--warn); }
27	  .layout { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 14px; align-items: start; }
28	  @media (max-width: 820px) { .layout { grid-template-columns: minmax(0, 1fr); } }
29	  .stage { position: relative; background: #000; border: 1px solid var(--line); border-radius: 4px; aspect-ratio: 4 / 3; max-width: 100%; overflow: hidden; touch-action: none; }
30	  .stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
31	  #gl { cursor: grab; }
32	  #gl:active { cursor: grabbing; }
33	  #hud { pointer-events: none; }
34	  .hint { position: absolute; left: 10px; bottom: 8px; font: 11px var(--mono); color: var(--muted); pointer-events: none; }
35	  #status { position: absolute; inset: 0; display: grid; place-items: center; font: 13px var(--mono); color: var(--muted); padding: 16px; text-align: center; }
36	  aside { display: flex; flex-direction: column; gap: 14px; background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 14px; }
37	  fieldset { border: 0; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px; }
38	  legend { font: 600 11px var(--cond); text-transform: uppercase; letter-spacing: .08em; color: var(--muted); margin-bottom: 4px; padding: 0; }
39	  .seg { display: flex; border: 1px solid var(--line); border-radius: 3px; overflow: hidden; }
40	  .seg button { flex: 1; background: transparent; color: var(--text); border: 0; border-right: 1px solid var(--line); padding: 6px 4px; font: 12px var(--sans); cursor: pointer; }
41	  .seg button:last-child { border-right: 0; }
42	  .seg button[aria-pressed="true"] { background: var(--accent); color: #062326; font-weight: 500; }
43	  button:focus-visible, input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
44	  label.row { display: grid; grid-template-columns: 1fr auto; gap: 2px 8px; font-size: 12px; color: var(--muted); }
45	  label.row output { font: 12px var(--mono); color: var(--text); font-variant-numeric: tabular-nums; }
46	  label.row input[type=range] { grid-column: 1 / -1; width: 100%; accent-color: var(--accent); margin: 0; }
47	  label.check { display: flex; gap: 8px; align-items: center; font-size: 13px; }
48	  label.check input { accent-color: var(--accent); }
49	  .views { display: flex; gap: 6px; flex-wrap: wrap; }
50	  .views button { background: transparent; color: var(--text); border: 1px solid var(--line); border-radius: 3px; padding: 4px 9px; font: 12px var(--sans); cursor: pointer; }
51	  .views button:hover { border-color: var(--accent); }
52	  .note { font-size: 12px; color: var(--muted); margin: 0; }
53	  .note.warn { color: var(--warn); }
54	  h2 { font: 600 16px/1.3 var(--cond); margin: 22px 0 8px; letter-spacing: .01em; }
55	  .flat { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 14px; align-items: start; }
56	  @media (max-width: 820px) { .flat { grid-template-columns: minmax(0, 1fr); } }
57	  .flat canvas { width: 100%; max-width: 100%; aspect-ratio: 1; image-rendering: pixelated; background: #000; border: 1px solid var(--line); border-radius: 4px; display: block; }
58	  .cap { font: 12px var(--mono); color: var(--muted); margin-top: 4px; }
59	  .depth svg { width: 100%; height: auto; display: block; }
60	  .depth { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 12px; display: flex; flex-direction: column; gap: 8px; }
61	  .legend-bar { height: 8px; border-radius: 2px; background: linear-gradient(90deg, #3e4fb8, #29a8e6, #2fe0a0, #b7f23a, #f7b92a, #e8551a); }
62	  .legend-ends { display: flex; justify-content: space-between; font: 11px var(--mono); color: var(--muted); }
63	  p.lede { max-width: 72ch; color: var(--muted); margin: 0 0 12px; }
64	  .review[hidden] { display: none; }
65	  .verdicts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
66	  .verdicts button, .tool { background: transparent; color: var(--text); border: 1px solid var(--line); border-radius: 3px; padding: 6px 4px; font: 12px var(--sans); cursor: pointer; }
67	  .verdicts button[aria-pressed="true"] { background: var(--text); color: var(--ground); font-weight: 500; }
68	  .tool[aria-pressed="true"] { border-color: var(--mark); color: var(--mark); }
69	  .verdicts button:disabled { opacity: .4; cursor: default; }
70	  #sel { font: 12px/1.5 var(--mono); color: var(--text); min-height: 3em; margin: 0; }
71	  #sel-note { width: 100%; background: var(--ground); color: var(--text); border: 1px solid var(--line); border-radius: 3px; padding: 5px 6px; font: 12px var(--sans); }
72	  .progress { font: 12px var(--mono); color: var(--muted); }
73	  .key { display: flex; flex-wrap: wrap; gap: 4px 12px; font: 11px var(--mono); color: var(--muted); }
74	  .key i { display: inline-block; width: 16px; height: 0; vertical-align: middle; margin-right: 4px; border-top: 2px solid #fff; }
75	  .edges-wrap { max-height: 320px; overflow: auto; border: 1px solid var(--line); border-radius: 4px; }
76	  table.edges { width: 100%; border-collapse: collapse; font: 12px var(--mono); font-variant-numeric: tabular-nums; }
77	  table.edges th { position: sticky; top: 0; background: var(--panel); text-align: right; font-weight: 500; color: var(--muted); padding: 5px 8px; border-bottom: 1px solid var(--line); }
78	  table.edges td { text-align: right; padding: 3px 8px; border-bottom: 1px solid #172026; cursor: pointer; }
79	  table.edges th:first-child, table.edges td:first-child, table.edges td:last-child, table.edges th:last-child { text-align: left; }
80	  table.edges tr.on td { background: #1d2a31; }
81	  .flat-stage { position: relative; }
82	  #flat-all.picking { cursor: crosshair; }
83	  @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
84	</style>
85	
86	<header>
87	  <h1>CD31 stack in 3D</h1>
88	  <div class="facts" id="facts"><span>loading…</span></div>
89	</header>
90	<p class="lede">Each of the 30 confocal slices is stacked at its depth. Drag to turn the stack; the view opens looking straight down, as the microscope does, which is the same picture as flattening every slice into one. Tilt it to see which crossings are real junctions and which are vessels passing over each other at different depths.</p>
91	
92	<div class="layout">
93	  <div>
94	    <div class="stage" id="stage">
95	      <canvas id="gl"></canvas>
96	      <canvas id="hud"></canvas>
97	      <div class="hint">drag: rotate · shift-drag or two fingers: pan · wheel or pinch: zoom</div>
98	      <div id="status">Loading the stack…</div>
99	    </div>
100	  </div>
101	  <aside>
102	    <fieldset class="review" id="review" hidden>
103	      <legend>Your review of the draft</legend>
104	      <label class="check"><input type="checkbox" id="show-graph" checked> Show traced vessels</label>
105	      <p id="sel">Click a line or a junction circle in either picture to review it.</p>
106	      <div class="verdicts" id="verdicts">
107	        <button type="button" data-v="right" disabled>Right</button>
108	        <button type="button" data-v="wrong" disabled>Wrong</button>
109	        <button type="button" data-v="unsure" disabled>Unsure</button>
110	      </div>
111	      <input type="text" id="sel-note" placeholder="Note on this item (optional)" disabled>
112	      <button type="button" class="tool" id="miss-del" hidden>Remove this missed mark</button>
113	      <button type="button" class="tool" id="miss-mode" aria-pressed="false">Mark missed vessels</button>
114	      <p class="note" id="miss-note">Turn this on, then click a vessel the draft missed in the flattened picture below.</p>
115	      <p class="progress" id="progress"></p>
116	      <p class="note warn" id="save-note"></p>
117	    </fieldset>
118	    <fieldset>
119	      <legend>Render</legend>
120	      <div class="seg" id="mode">
121	        <button type="button" id="mode-mip" data-v="0" aria-pressed="true">Brightest</button>
122	        <button type="button" id="mode-surf" data-v="1" aria-pressed="false">Surface</button>
123	      </div>
124	      <p class="note" id="mode-note">Each ray shows the brightest point it passes through.</p>
125	    </fieldset>
126	    <fieldset>
127	      <legend>Channel</legend>
128	      <div class="seg" id="chan">
129	        <button type="button" id="chan-cd31" data-v="0" aria-pressed="true">CD31</button>
130	        <button type="button" id="chan-dapi" data-v="1" aria-pressed="false">DAPI</button>
131	        <button type="button" id="chan-both" data-v="2" aria-pressed="false">Both</button>
132	      </div>
133	      <label class="check"><input type="checkbox" id="depth" checked> Colour by depth</label>
134	    </fieldset>
135	    <fieldset>
136	      <legend>Brightness</legend>
137	      <label class="row">Black point <output id="lo-o"></output><input type="range" id="lo" min="0" max="1" step="0.005" value="0.63"></label>
138	      <label class="row">White point <output id="hi-o"></output><input type="range" id="hi" min="0" max="1" step="0.005" value="1"></label>
139	      <label class="row" id="iso-row">Surface level <output id="iso-o"></output><input type="range" id="iso" min="0" max="1" step="0.005" value="0.35"></label>
140	    </fieldset>
141	    <fieldset>
142	      <legend>Depth</legend>
143	      <label class="row">Show slices from <output id="z0-o"></output><input type="range" id="z0" min="0" max="29" step="1" value="0"></label>
144	      <label class="row">to <output id="z1-o"></output><input type="range" id="z1" min="0" max="29" step="1" value="29"></label>
145	      <label class="row">Spacing between slices <output id="zs-o"></output><input type="range" id="zs" min="0.25" max="10" step="0.05" value="1"></label>
146	      <p class="note warn" id="zs-note"></p>
147	    </fieldset>
148	    <fieldset>
149	      <legend>Look from</legend>
150	      <div class="views">
151	        <button type="button" id="v-top">Top</button>
152	        <button type="button" id="v-tilt">Tilted</button>
153	        <button type="button" id="v-side">Side</button>
154	        <button type="button" id="v-front">Front</button>
155	      </div>
156	    </fieldset>
157	  </aside>
158	</div>
159	
160	<h2>Flattened against one slice</h2>
161	<div class="flat">
162	  <div>
163	    <canvas id="flat-all"></canvas>
164	    <div class="cap" id="cap-all">All shown slices, brightest value per pixel</div>
165	  </div>
166	  <div>
167	    <canvas id="flat-one"></canvas>
168	    <label class="row" style="margin-top:6px">Single slice <output id="sl-o"></output><input type="range" id="sl" min="0" max="29" step="1" value="15"></label>
169	  </div>
170	</div>
171	
172	<section class="review" id="edges-sec" hidden>
173	  <h2>Traced vessels</h2>
174	  <div class="key" style="margin-bottom:8px"><span><i style="border-top-style:dashed"></i>not reviewed</span><span><i></i>right</span><span><i style="border-color:var(--mark)"></i>wrong</span><span><i style="border-color:var(--mark);border-top-style:dashed"></i>unsure</span><span><i style="border-color:var(--mark);width:8px"></i>+ missed</span><span>○ junction</span><span>× crossing</span></div>
175	  <div class="edges-wrap"><table class="edges"><thead><tr><th>Edge</th><th>Nodes</th><th>Length µm</th><th>Width µm</th><th>± sd</th><th id="depth-col">Depth µm</th><th>Your mark</th></tr></thead><tbody id="edge-rows"></tbody></table></div>
176	  <p class="note" style="margin-top:8px"><span id="edges-note">Length runs along the traced 3D centerline; width is twice the distance from it to the traced edge, so the 20× axial blur widens vessels running through depth. Depth uses the guessed slice spacing.</span> <button type="button" class="tool" id="dl" hidden>Download the graph with your marks</button></p>
177	</section>
178	
179	<h2>Signal through the depth</h2>
180	<div class="depth">
181	  <svg id="spark" viewBox="0 0 1100 170" role="img" aria-label="Per-slice brightness"></svg>
182	  <div class="facts"><span style="color:#e8b04a">━ brightest 1% of pixels (vessels)</span><span>━ median pixel (background)</span><span style="color:#4fd1d9">┆ single slice shown above</span></div>
183	  <div id="depth-legend" hidden>
184	    <div class="legend-bar"></div>
185	    <div class="legend-ends"><span>first slice</span><span>depth colour</span><span>last slice</span></div>
186	  </div>
187	  <p class="note" id="drift-note"></p>
188	</div>
189	
190	<script>
191	(() => {
192	'use strict';
193	const $ = (id) => document.getElementById(id);
194	const status = (t) => { const s = $('status'); s.textContent = t; s.hidden = !t; };
195	
196	// ---------- small matrix kit (column-major, as WebGL expects) ----------
197	const M = {
198	  persp(fovy, asp, n, f) { const t = 1 / Math.tan(fovy / 2), r = 1 / (n - f);
199	    return [t / asp,0,0,0, 0,t,0,0, 0,0,(n + f) * r,-1, 0,0,2 * n * f * r,0]; },
200	  look(e, c, u) {
201	    const sub = (a, b) => [a[0]-b[0], a[1]-b[1], a[2]-b[2]];
202	    const nrm = (a) => { const l = Math.hypot(...a); return a.map(x => x / l); };
203	    const cr = (a, b) => [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
204	    const z = nrm(sub(e, c)), x = nrm(cr(u, z)), y = cr(z, x);
205	    const d = (a, b) => a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
206	    return [x[0],y[0],z[0],0, x[1],y[1],z[1],0, x[2],y[2],z[2],0, -d(x,e),-d(y,e),-d(z,e),1]; },
207	  mul(a, b) { const o = new Array(16).fill(0);
208	    for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) for (let k = 0; k < 4; k++) o[c*4+r] += a[k*4+r] * b[c*4+k];
209	    return o; },
210	  inv(m) { const i = new Array(16);
211	    i[0]=m[5]*m[10]*m[15]-m[5]*m[11]*m[14]-m[9]*m[6]*m[15]+m[9]*m[7]*m[14]+m[13]*m[6]*m[11]-m[13]*m[7]*m[10];
212	    i[4]=-m[4]*m[10]*m[15]+m[4]*m[11]*m[14]+m[8]*m[6]*m[15]-m[8]*m[7]*m[14]-m[12]*m[6]*m[11]+m[12]*m[7]*m[10];
213	    i[8]=m[4]*m[9]*m[15]-m[4]*m[11]*m[13]-m[8]*m[5]*m[15]+m[8]*m[7]*m[13]+m[12]*m[5]*m[11]-m[12]*m[7]*m[9];
214	    i[12]=-m[4]*m[9]*m[14]+m[4]*m[10]*m[13]+m[8]*m[5]*m[14]-m[8]*m[6]*m[13]-m[12]*m[5]*m[10]+m[12]*m[6]*m[9];
215	    i[1]=-m[1]*m[10]*m[15]+m[1]*m[11]*m[14]+m[9]*m[2]*m[15]-m[9]*m[3]*m[14]-m[13]*m[2]*m[11]+m[13]*m[3]*m[10];
216	    i[5]=m[0]*m[10]*m[15]-m[0]*m[11]*m[14]-m[8]*m[2]*m[15]+m[8]*m[3]*m[14]+m[12]*m[2]*m[11]-m[12]*m[3]*m[10];
217	    i[9]=-m[0]*m[9]*m[15]+m[0]*m[11]*m[13]+m[8]*m[1]*m[15]-m[8]*m[3]*m[13]-m[12]*m[1]*m[11]+m[12]*m[3]*m[9];
218	    i[13]=m[0]*m[9]*m[14]-m[0]*m[10]*m[13]-m[8]*m[1]*m[14]+m[8]*m[2]*m[13]+m[12]*m[1]*m[10]-m[12]*m[2]*m[9];
219	    i[2]=m[1]*m[6]*m[15]-m[1]*m[7]*m[14]-m[5]*m[2]*m[15]+m[5]*m[3]*m[14]+m[13]*m[2]*m[7]-m[13]*m[3]*m[6];
220	    i[6]=-m[0]*m[6]*m[15]+m[0]*m[7]*m[14]+m[4]*m[2]*m[15]-m[4]*m[3]*m[14]-m[12]*m[2]*m[7]+m[12]*m[3]*m[6];
221	    i[10]=m[0]*m[5]*m[15]-m[0]*m[7]*m[13]-m[4]*m[1]*m[15]+m[4]*m[3]*m[13]+m[12]*m[1]*m[7]-m[12]*m[3]*m[5];
222	    i[14]=-m[0]*m[5]*m[14]+m[0]*m[6]*m[13]+m[4]*m[1]*m[14]-m[4]*m[2]*m[13]-m[12]*m[1]*m[6]+m[12]*m[2]*m[5];
223	    i[3]=-m[1]*m[6]*m[11]+m[1]*m[7]*m[10]+m[5]*m[2]*m[11]-m[5]*m[3]*m[10]-m[9]*m[2]*m[7]+m[9]*m[3]*m[6];
224	    i[7]=m[0]*m[6]*m[11]-m[0]*m[7]*m[10]-m[4]*m[2]*m[11]+m[4]*m[3]*m[10]+m[8]*m[2]*m[7]-m[8]*m[3]*m[6];
225	    i[11]=-m[0]*m[5]*m[11]+m[0]*m[7]*m[9]+m[4]*m[1]*m[11]-m[4]*m[3]*m[9]-m[8]*m[1]*m[7]+m[8]*m[3]*m[5];
226	    i[15]=m[0]*m[5]*m[10]-m[0]*m[6]*m[9]-m[4]*m[1]*m[10]+m[4]*m[2]*m[9]+m[8]*m[1]*m[6]-m[8]*m[2]*m[5];
227	    const det = m[0]*i[0] + m[1]*i[4] + m[2]*i[8] + m[3]*i[12];
228	    return i.map(x => x / det); },
229	  xf(m, p) { const v = [0,0,0,0];
230	    for (let r = 0; r < 4; r++) v[r] = m[r]*p[0] + m[4+r]*p[1] + m[8+r]*p[2] + m[12+r];
231	    return v; },
232	};
233	
