// "Load from Google Drive": the user pastes the link of an image or a folder shared as "Anyone
// with the link", with no sign-in. Google answers a page on another site only through the Drive
// API with an API key (NOR_CONFIG.google.apiKey, written into config.js at deploy): its plain download link refuses any
// request a browser marks cross-site. Nothing is kept: the file goes to the finder like one loaded
// from the computer.
"use strict";
window.NorDrive = (() => {
  const key = ((window.NOR_CONFIG && window.NOR_CONFIG.google) || {}).apiKey || "";
  const API = "https://www.googleapis.com/drive/v3/files";

  // {kind: "file" | "folder", id} from any Drive link; a bare id is looked up
  function parse(link) {
    const s = link.trim();
    let m = s.match(/\/folders\/([\w-]{10,})/);
    if (m) return { kind: "folder", id: m[1] };
    m = s.match(/\/file\/d\/([\w-]{10,})/) || s.match(/[?&]id=([\w-]{10,})/) || s.match(/^([\w-]{20,})$/);
    return m ? { kind: "file", id: m[1] } : null;
  }

  const need = () => { if (!key) throw new Error("this site has no Google API key yet (issue #234)"); };
  const refused = (r, what) => new Error(r.status === 400
    ? `Google refused this site's API key (${r.status})`
    : `Drive refused the ${what} (${r.status}): is it shared as "Anyone with the link"?`);

  // onStart(name) runs once the download begins and onChunk(buffer, got, total) as each piece arrives,
  // the bytes so far at the start of buffer; total is null when Drive does not say
  async function file(id, name, onStart, onChunk) {
    need();
    const at = `${API}/${encodeURIComponent(id)}`;
    if (!name) {
      const r = await fetch(`${at}?fields=name,mimeType&key=${key}`);
      if (!r.ok) throw refused(r, "file");
      const f = await r.json();
      if (f.mimeType === "application/vnd.google-apps.folder") return { folder: true, id, name: f.name };
      name = f.name;
    }
    const r = await fetch(`${at}?alt=media&key=${key}`);
    if (!r.ok) throw refused(r, "file");
    if (onStart) onStart(name);
    const total = +r.headers.get("content-length") || null;
    if (!onChunk || !r.body) return { name, bytes: await r.arrayBuffer() };
    let buf = new ArrayBuffer(total || 1 << 20), got = 0;
    for (const reader = r.body.getReader(); ; ) {
      const { done, value } = await reader.read();
      if (done) break;
      if (got + value.length > buf.byteLength) {
        const more = new ArrayBuffer(Math.max(2 * buf.byteLength, got + value.length));
        new Uint8Array(more).set(new Uint8Array(buf, 0, got)); buf = more;
      }
      new Uint8Array(buf, got).set(value); got += value.length;
      onChunk(buf, got, total);
    }
    return { name, bytes: got === buf.byteLength ? buf : buf.slice(0, got) };
  }

  // [{id, name, folder, size, created}] in a public folder: its subfolders and its TIFF and PNG images;
  // size in bytes (null for a folder), created a Date
  async function list(id) {
    need();
    const q = encodeURIComponent(`'${id}' in parents and trashed = false`);
    const r = await fetch(`${API}?q=${q}&fields=files(id,name,mimeType,size,createdTime)&pageSize=1000&orderBy=folder,name&key=${key}`);
    if (!r.ok) throw refused(r, "folder");
    return (await r.json()).files
      .map((f) => ({ id: f.id, name: f.name, folder: f.mimeType === "application/vnd.google-apps.folder",
        size: f.size == null ? null : +f.size, created: f.createdTime ? new Date(f.createdTime) : null }))
      .filter((f) => f.folder || /\.(tiff?|png)$/i.test(f.name));
  }

  return { parse, file, list, ready: !!key };
})();

// ---------- loading ----------
async function openBytes(name, bytes) {
  st.fileName = name; st.meta = null; st.lastRun = null; st.cands = []; st.order = []; st.sel = null; st.ring = null; st.crops = new Map();
  st.sha = [...new Uint8Array(await crypto.subtle.digest("SHA-256", bytes))].map((b) => b.toString(16).padStart(2, "0")).join("");
  $("#file-name").textContent = name; $("#file-name").classList.remove("dim"); statusBar();
  $("#overlay").innerHTML = ""; $("#list").replaceChildren(); $("#summary").textContent = "No candidates yet.";
  $("#switch").disabled = true; $("#sb-counts").textContent = ""; downloads(false); renderSelected();
  if (st.ready) return send(name, bytes);
  // Python is still loading: the image opens the moment it is ready
  st.queued = { name, bytes }; busy(true, "Python is still loading; your image opens as soon as it is ready…", st.peeked && "peek"); loadShine();
}
function send(name, bytes) {
  busy(true, "Reading the image…", st.peeked && "peek");
  st.worker.postMessage({ type: "open", name, bytes }, [bytes]);
}
// a painter for the image's bytes as they arrive (peek.js), shown until Python's own drawing replaces it
function peek() {
  st.peeked = false;
  const shown = () => ["show-r", "show-g", "show-b"].map((id) => $("#" + id).checked);
  return (st.peek = NorPeek.painter($("#base"), shown, (W, H) => {
    st.img = null; st.plain = null; st.W = W; st.H = H; st.peeked = true;
    $("#overlay").innerHTML = ""; $("#empty").hidden = true; $("#stage").hidden = false; $("#thumb-wrap").hidden = true;
    setZoom(st.zoom); updateFind();
  }));
}
// Load shimmers until there is an image to work on
const loadShine = () => $("#load-main").classList.toggle("shine", !st.img && !st.queued);
$("#file").onchange = async (e) => {
  const f = e.target.files[0]; if (!f) return;
  const bytes = await f.arrayBuffer(); peek()(bytes, bytes.byteLength);
  openBytes(f.name, bytes); e.target.value = "";
};
function load(src) {
  writeJSON(SOURCE, src); $("#load-menu").open = false;
  if (src === "local") return $("#file").click();
  const home = ((window.NOR_CONFIG || {}).drive || {}).defaultLink || "";
  $("#drive-link").value = readJSON(DRIVE_LINK, "") || home; $("#drive-dlg").showModal(); $("#drive-link").select();
  if (NorDrive.parse($("#drive-link").value)?.kind === "folder") $("#drive-go").click();
}
$("#load-main").onclick = () => load(readJSON(SOURCE, "local"));
document.querySelectorAll("#load-menu .item").forEach((b) => (b.onclick = () => load(b.dataset.src)));

// the Drive dialog: a pasted file link loads at once; a folder link lists its images and subfolders
{
  const msg = (t, err) => { const m = $("#drive-msg"); m.textContent = m.title = t; m.classList.toggle("err", !!err); };
  const sizeText = (n) => (n < 1048576 ? `${Math.max(1, Math.round(n / 1024))} KB` : `${(n / 1048576).toFixed(1)} MB`);
  let trail = [];
  const take = async (id, name) => {
    msg("Downloading " + (name || "the image") + "…");
    const mb = (n) => (n / 1048576).toFixed(1);
    let push, what;
    try {
      const f = await NorDrive.file(id, name, (n) => {
        what = n; $("#drive-dlg").close(); msg(""); push = peek(); busy(true, `Downloading ${n}…`, "peek");
      }, (buf, got, total) => {
        push(buf, got);
        $("#busy-text").textContent = `Downloading ${what} · ${mb(got)}${total ? " of " + mb(total) : ""} MB`;
      });
      if (f.folder) { trail = [f]; return show(); }
      openBytes(f.name, f.bytes);
    } catch (err) {
      busy(false); if (!$("#drive-dlg").open) $("#drive-dlg").showModal();
      msg(err.message || String(err), true);
    }
  };
  const show = async () => {
    const at = trail[trail.length - 1];
    $("#drive-path").innerHTML = trail.map((t, k) => `<button type="button" class="link" data-k="${k}">${esc(t.name)}</button>`).join(" / ");
    $("#drive-path").querySelectorAll("button").forEach((b) => (b.onclick = () => { trail = trail.slice(0, +b.dataset.k + 1); show(); }));
    $("#drive-path").scrollLeft = $("#drive-path").scrollWidth;
    $("#drive-list").replaceChildren(); msg("Reading the folder…");
    try {
      const items = await NorDrive.list(at.id);
      msg(items.length ? "" : "No TIFF or PNG images here.");
      for (const f of items) {
        const b = document.createElement("button"); b.type = "button"; b.className = "item" + (f.folder ? " folder" : "");
        const meta = [f.size == null ? "" : sizeText(f.size),
          f.created ? f.created.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : ""].filter(Boolean).join(" · ");
        b.innerHTML = `<span class="name">${esc(f.name)}</span><span class="meta">${esc(meta)}</span>`;
        b.onclick = () => (f.folder ? (trail.push(f), show()) : take(f.id, f.name));
        $("#drive-list").append(b);
      }
    } catch (err) { msg(err.message || String(err), true); }
  };
  if (!NorDrive.ready) {
    const d = document.querySelector('#load-menu .item[data-src="drive"]');
    d.disabled = true; d.title = "Needs this site's Google API key (issue #234)";
  }
  const open = () => {
    const link = $("#drive-link").value, ref = NorDrive.parse(link);
    $("#drive-list").replaceChildren(); $("#drive-path").replaceChildren();
    if (!ref) return msg("That does not look like a Google Drive link.", true);
    writeJSON(DRIVE_LINK, link);
    if (ref.kind === "file") return take(ref.id);
    trail = [{ id: ref.id, name: "Folder" }]; show();
  };
  $("#drive-go").onclick = open;
  $("#drive-link").addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); open(); } });
}

// ---------- image ----------
function drawBase() {
  const c = $("#base"); c.width = st.W; c.height = st.H;
  const ctx = c.getContext("2d"), im = ctx.createImageData(st.W, st.H), d = im.data;
  const R = $("#show-r").checked, G = $("#show-g").checked, B = $("#show-b").checked, { r, g, b } = st.img;
  for (let i = 0, j = 0; i < r.length; i++, j += 4) { d[j] = R ? r[i] : 0; d[j + 1] = G ? g[i] : 0; d[j + 2] = B ? b[i] : 0; d[j + 3] = 255; }
  ctx.putImageData(im, 0, 0);
  // an unmodified copy for the crops
  if (!st.plain) {
    st.plain = document.createElement("canvas"); st.plain.width = st.W; st.plain.height = st.H;
// Paints the lab's images (uncompressed three-channel ImageJ TIFFs) while their bytes arrive, so the image
// shows before it has finished downloading and before Python has read it; Python's own drawing replaces it
// once the image is open. Channels get the roles Python gives them (naive_nor.load): Caspr is the channel
// ImageJ displays green, DAPI the other with the larger blobs, Nav the rest. Until both of the others are in
// far enough to tell them apart they show grey. Anything else is left alone: push() then returns false.
"use strict";
window.NorPeek = (() => {
  const TAGS = { 256: "W", 257: "H", 258: "bits", 259: "comp", 270: "desc", 273: "offsets", 277: "spp", 50838: "ijCounts", 50839: "ijData" };
  const SIZE = { 1: 1, 2: 1, 3: 2, 4: 4, 7: 1, 16: 8 };
  const NAV = 0, CASPR = 1, DAPI = 2;
  const JUDGE = 1 / 3; // the share of rows of both other channels compared to tell DAPI from Nav

  // the first page's tags, undefined while more bytes are needed, null when the file is not one to paint.
  // ImageJ writes its channels' pixels back to back after the first page and the other pages' tags at the
  // end of the file, so the first page tells where every channel is.
  function layout(dv, got) {
    if (got < 8) return undefined;
    const le = dv.getUint16(0) === 0x4949, u16 = (o) => dv.getUint16(o, le), u32 = (o) => dv.getUint32(o, le);
    if (u16(2) !== 42) return null;
    const off = u32(4);
    if (off + 2 > got) return undefined;
    const n = u16(off);
    if (off + 2 + 12 * n > got) return undefined;
    const t = {};
    for (let e = 0; e < n; e++) {
      const at = off + 2 + 12 * e, name = TAGS[u16(at)];
      if (!name) continue;
      const type = u16(at + 2), count = u32(at + 4), size = SIZE[type] || 1;
      const where = count * size <= 4 ? at + 8 : u32(at + 8);
      if (where + count * size > got) return undefined;
      const read = (k) => (type === 3 ? u16(where + 2 * k) : type === 4 ? u32(where + 4 * k) : dv.getUint8(where + k));
      t[name] = name === "ijData" ? { where, le } : Array.from({ length: count }, (_, k) => read(k));
    }
    const W = t.W?.[0], H = t.H?.[0], bits = t.bits?.[0];
    const desc = t.desc ? String.fromCharCode(...t.desc) : "";
    if (!/^ImageJ=/.test(desc) || !/\bimages=3\b/.test(desc) || !W || !H || !t.offsets || ![8, 16].includes(bits)) return null;
    if ((t.comp?.[0] ?? 1) !== 1 || (t.spp?.[0] ?? 1) !== 1) return null;
    const caspr = greenPage(dv, t);
    if (caspr == null) return null;
    const bpp = bits / 8;
    return { le, W, H, bpp, starts: [0, 1, 2].map((k) => t.offsets[0] + k * W * H * bpp), caspr };
  }

  // the channel ImageJ displays green: its LUT ends brightest in green
  function greenPage(dv, t) {
    if (!t.ijCounts || !t.ijData) return null;
    const at = t.ijData.where, tag = (o) => String.fromCharCode(...[0, 1, 2, 3].map((k) => dv.getUint8(o + k)));
    if (tag(at) !== "IJIJ" && tag(at) !== "JIJI") return null;
    const le = tag(at) === "JIJI", sizes = t.ijCounts, tops = [];
    let pos = at + sizes[0], block = 1;
    for (let h = 4; h + 8 <= sizes[0]; h += 8) {
      const type = tag(at + h), count = dv.getUint32(at + h + 4, le);
      for (let c = 0; c < count; c++, block++) {
        if (type === "tuls" || type === "luts") tops.push([0, 1, 2].map((k) => dv.getUint8(pos + 256 * k + 255)));
        pos += sizes[block];
      }
    }
    const green = tops.map((v) => v.indexOf(Math.max(...v)) === 1);
    return tops.length === 3 && green.filter(Boolean).length === 1 ? green.indexOf(true) : null;
  }

  // naive_nor.blob_area over the first rows of a channel: the mean size of the pieces its brightest 3% make
  // after a sigma-2 blur, large for nuclei
  function blobArea(v, W, H) {
    const R = 6, k = Array.from({ length: 2 * R + 1 }, (_, i) => Math.exp(-((i - R) ** 2) / 8));
    const s = k.reduce((a, b) => a + b), mirror = (i, n) => (i < 0 ? -i - 1 : i >= n ? 2 * n - i - 1 : i);
    const a = new Float32Array(W * H), b = new Float32Array(W * H);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      let t = 0; for (let i = -R; i <= R; i++) t += k[i + R] * v[y * W + mirror(x + i, W)]; a[y * W + x] = t / s;
    }
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
