+    } else {
+      if (next < 4096) { prefix[next] = prev; suffix[next] = first(prev); len[next] = len[prev] + 1; next++; }
+      emit(code);
+    }
+    prev = code;
+    if (next + 1 >= 1 << width && width < 12) width++;
