  Object.assign(S, { z0: 0, z1: Z - 1, yaw: 0, pitch: 0, dist: 4.4, pan: [0, 0] });
  let saved = null;
  try { saved = localStorage.getItem(CHANNEL_KEY); } catch { /* no storage */ }
  S.chan = saved != null && +saved < vols.length ? +saved : 0;
